mapper.select:
SELECT term.id AS termId, term.term_name AS termName, cc.id AS courseClassId, sd.id AS sessionId, sd.teacher_id AS teacherId, sd.session_date AS sessionDate, sd.week_day AS weekDay, sd.start_time AS startTime, sd.end_time AS endTime, sd.place_name AS placeName, cc.course_class_name AS courseClassName FROM t_as_student_destination dest INNER JOIN t_as_course_session sd ON dest.session_id = sd.id INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_educl_term term ON svc.term_id = term.id AND term.is_valid = 1 INNER JOIN t_as_student stu ON dest.student_id = stu.id AND stu.is_valid = 1 AND stu.term_id = svc.term_id INNER JOIN t_as_enrollment ae ON sd.id = ae.session_id and dest.student_id = ae.student_id and ae.is_valid = 1
dest.is_valid = 1 AND sd.is_valid = 1 AND cc.is_valid = 1 and ae.enroll_status in(1,3) AND dest.destination_type = 1
AND dest.school_id = #{query.schoolId}
AND dest.student_id = #{query.studentId}
AND svc.term_id = #{query.termId}
AND sd.session_date BETWEEN #{weekStartDate} AND #{weekEndDate}
AND sd.session_date BETWEEN #{monthStartDate} AND #{monthEndDate}
AND sd.session_date = #{dayDate}
ORDER BY sd.session_date ASC, sd.start_time ASC

SELECT cc.id AS courseClassId, sd.id AS sessionId, sd.teacher_id AS teacherId, sd.session_date AS sessionDate, sd.week_day AS weekDay, sd.start_time AS startTime, sd.end_time AS endTime, sd.place_name AS placeName, cc.course_class_name AS courseClassName FROM t_as_course_session sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id
sd.is_valid = 1 AND cc.is_valid = 1
AND sd.school_id = #{query.schoolId}
AND sd.teacher_id = #{query.teacherId}
AND sd.session_date BETWEEN #{weekStartDate} AND #{weekEndDate}
AND sd.session_date BETWEEN #{monthStartDate} AND #{monthEndDate}
AND sd.session_date = #{dayDate}
ORDER BY sd.session_date ASC, sd.start_time ASC

SELECT term.id AS termId, term.term_name AS termName, sd.id AS sessionId, sd.start_time AS startTime, sd.end_time AS endTime, sd.course_class_id AS courseClassId, cc.course_class_name AS courseClassName, (SELECT g.grade_name FROM t_as_enrollment enr INNER JOIN t_as_student stu ON enr.student_id = stu.id LEFT JOIN t_educl_grade g ON stu.grade_id = g.id and g.is_valid = 1 WHERE enr.course_class_id = cc.id AND enr.is_valid = 1 AND stu.is_valid = 1 AND stu.grade_id IS NOT NULL LIMIT 1) AS gradeName, sd.place_name AS placeName, sd.session_date AS sessionDate, sd.teacher_id AS teacherId, t.teacher_name AS teacherName, cc.intro AS intro, cc.enroll_type AS enrollType, CASE cc.enroll_type WHEN 1 THEN '公开报名' WHEN 2 THEN '邀请报名' WHEN 3 THEN '行政班安排' END AS enrollTypeName, cat.category_name AS categoryName FROM t_as_course_session sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_educl_term term ON svc.term_id = term.id AND term.is_valid = 1 INNER JOIN t_as_teacher t ON sd.teacher_id = t.id LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id
sd.is_valid = 1 AND cc.is_valid = 1 AND t.is_valid = 1 AND sd.id = #{sessionId} AND sd.teacher_id = #{teacherId}
LIMIT 1

SELECT cc.course_class_name AS courseClassName, t.teacher_name AS teacherName, cc.enroll_type AS enrollType, DATE_FORMAT(cs.session_date, '%Y-%m-%d') AS sessionDate, DATE_FORMAT(cs.start_time, '%H:%i') AS sessionStartTime, DATE_FORMAT(cs.end_time, '%H:%i') AS sessionEndTime FROM t_as_course_session cs INNER JOIN t_as_course_class cc ON cs.course_class_id = cc.id AND cc.is_valid = 1 LEFT JOIN t_as_teacher t ON cs.teacher_id = t.id AND t.is_valid = 1 WHERE cs.is_valid = 1 AND cs.id IN
#{id}
ORDER BY cs.session_date ASC, cs.start_time ASC
